let generatedData = null;

// Embedded ECU logo for a guaranteed origin-clean attendance-card canvas.
const ECU_LOGO_DATA_URL = "data:image/png;base64,";

document.addEventListener("DOMContentLoaded", () => {
  initializeSelectors();
  applyLanguage();

  document.getElementById("studentForm").addEventListener("submit", handleGenerate);
  document.getElementById("clearBtn").addEventListener("click", clearForm);
  document.getElementById("generateAgainBtn").addEventListener("click", () => {
    document.getElementById("resultPanel").classList.add("hidden");
    document.getElementById("formPanel").classList.remove("hidden");
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
  document.getElementById("languageToggle").addEventListener("click", () => {
    currentLanguage = currentLanguage === "en" ? "ar" : "en";
    applyLanguage();
    if (generatedData) renderCard(generatedData);
  });
  document.getElementById("downloadPngBtn").addEventListener("click", downloadPng);
  document.getElementById("downloadPdfBtn").addEventListener("click", downloadPdf);
  document.getElementById("printBtn").addEventListener("click", () => window.print());
});

function initializeSelectors() {
  const university = document.getElementById("university");
  university.innerHTML = `<option value="">${t("choose")}</option>`;
  UNIVERSITY_CONFIG.universities.forEach(u => {
    const option = document.createElement("option");
    option.value = u.id;
    option.textContent = localName(u);
    university.appendChild(option);
  });

  university.addEventListener("change", populateFaculties);
}

function populateFaculties() {
  const u = UNIVERSITY_CONFIG.universities.find(x => x.id === document.getElementById("university").value);
  const faculty = document.getElementById("faculty");

  faculty.innerHTML = `<option value="">${t("choose")}</option>`;

  if (!u) {
    faculty.disabled = true;
    return;
  }

  u.faculties.forEach(f => {
    const option = document.createElement("option");
    option.value = f.id;
    option.textContent = localName(f);
    faculty.appendChild(option);
  });
  faculty.disabled = false;
}

async function handleGenerate(event) {
  event.preventDefault();
  const result = validateForm();
  if (!result.valid) return;

  const u = UNIVERSITY_CONFIG.universities.find(x => x.id === result.values.university);
  const f = u.faculties.find(x => x.id === result.values.faculty);

  generatedData = {
    universityId: u.id,
    facultyId: f.id,
    university: localName(u),
    faculty: localName(f),
    studentName: result.values.name,
    studentId: result.values.id
  };

  generatedData.payload = buildQrPayload(generatedData);
  renderCard(generatedData);

  document.getElementById("formPanel").classList.add("hidden");
  document.getElementById("resultPanel").classList.remove("hidden");
  showToast(t("generated"));
  window.scrollTo({ top: 0, behavior: "smooth" });
}

async function renderCard(data) {
  document.getElementById("cardUniversity").textContent = data.university;
  document.getElementById("cardFaculty").textContent = data.faculty;
  document.getElementById("cardStudentName").textContent = data.studentName;
  document.getElementById("cardStudentId").textContent = data.studentId;

  try {
    const result = await generateStudentQr(data.payload, document.getElementById("qrContainer"));
    data.qrCanvas = result.canvas;
    data.qrImage = result.img;
    data.qrDataUrl = result.canvas ? result.canvas.toDataURL("image/png") : result.img?.src;
  } catch (error) {
    console.error(error);
    showToast(error.message || "Unable to generate QR code.");
  }
}

window.refreshResultLanguage = () => {
  if (!generatedData) return;
  const u = UNIVERSITY_CONFIG.universities.find(x => x.id === generatedData.universityId);
  const f = u?.faculties.find(x => x.id === generatedData.facultyId);
  if (u && f) {
    generatedData.university = localName(u);
    generatedData.faculty = localName(f);
  }
};

function clearForm() {
  document.getElementById("studentForm").reset();
  clearErrors();
  document.getElementById("faculty").innerHTML = `<option value="">${t("choose")}</option>`;
  document.getElementById("faculty").disabled = true;
  generatedData = null;
  document.getElementById("resultPanel").classList.add("hidden");
  showToast(t("cleared"));
}

async function downloadPng() {
  if (!generatedData?.qrDataUrl) {
    showToast("Attendance card is not ready.");
    return;
  }

  try {
    const cardCanvas = await createAttendanceCardCanvas(generatedData);
    const a = document.createElement("a");
    a.href = cardCanvas.toDataURL("image/png", 1.0);
    a.download = safeFileName(
      generatedData.studentId + "_" + generatedData.studentName + "_STUDENT_ATTENDANCE_CARD"
    ) + ".png";
    document.body.appendChild(a);
    a.click();
    a.remove();
  } catch (error) {
    console.error(error);
    showToast(error.message || "Unable to create the attendance card image.");
  }
}

async function createAttendanceCardCanvas(data) {
  const canvas = document.createElement("canvas");
  canvas.width = 1600;
  canvas.height = 1000;

  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";

  // Card background.
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Outer border.
  ctx.strokeStyle = "#17365d";
  ctx.lineWidth = 14;
  roundedRectPath(ctx, 35, 35, 1530, 930, 36);
  ctx.stroke();

  // Header band.
  ctx.fillStyle = "#17365d";
  roundedRectPath(ctx, 42, 42, 1516, 190, 30);
  ctx.fill();

  // ECU logo.
  const logo = await loadImage(ECU_LOGO_DATA_URL);
  const logoBox = { x: 75, y: 68, w: 250, h: 135 };
  drawContain(ctx, logo, logoBox.x, logoBox.y, logoBox.w, logoBox.h);

  // Header text.
  ctx.fillStyle = "#ffffff";
  ctx.textAlign = "left";
  ctx.font = "700 44px Arial, sans-serif";
  ctx.fillText("EGYPTIAN CHINESE UNIVERSITY", 360, 105);

  ctx.font = "700 34px Arial, sans-serif";
  ctx.fillText("FACULTY OF COMPUTER AND INFORMATION SYSTEMS", 360, 157);

  ctx.font = "700 25px Arial, sans-serif";
  ctx.fillText("STUDENT ATTENDANCE CARD", 360, 198);

  // Student information.
  ctx.fillStyle = "#17365d";
  ctx.textAlign = "left";
  ctx.font = "700 34px Arial, sans-serif";
  ctx.fillText("STUDENT INFORMATION", 90, 315);

  ctx.strokeStyle = "#dbe3ec";
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(90, 345);
  ctx.lineTo(1040, 345);
  ctx.stroke();

  drawCardField(ctx, "UNIVERSITY", data.university, 90, 415, 800);
  drawCardField(ctx, "FACULTY", data.faculty, 90, 520, 800);
  drawCardField(ctx, "STUDENT NAME", data.studentName, 90, 650, 800);
  drawCardField(ctx, "STUDENT ID", data.studentId, 90, 775, 800);

  // QR panel.
  ctx.fillStyle = "#f6f8fb";
  roundedRectPath(ctx, 1080, 285, 395, 520, 28);
  ctx.fill();

  ctx.strokeStyle = "#d5dee8";
  ctx.lineWidth = 3;
  roundedRectPath(ctx, 1080, 285, 395, 520, 28);
  ctx.stroke();

  if (!data.qrCanvas) {
    throw new Error("QR canvas is not ready. Please generate the card again.");
  }
  drawContain(ctx, data.qrCanvas, 1125, 330, 305, 305);

  ctx.fillStyle = "#17365d";
  ctx.textAlign = "center";
  ctx.font = "700 25px Arial, sans-serif";
  ctx.fillText("SCAN FOR ATTENDANCE", 1277, 685);

  ctx.fillStyle = "#667085";
  ctx.font = "500 20px Arial, sans-serif";
  ctx.fillText("Present this card when attendance", 1277, 728);
  ctx.fillText("is being recorded.", 1277, 758);

  // Footer / ownership.
  ctx.fillStyle = "#eef3f8";
  roundedRectPath(ctx, 70, 850, 1460, 75, 18);
  ctx.fill();

  ctx.fillStyle = "#17365d";
  ctx.textAlign = "center";
  ctx.font = "700 24px Arial, sans-serif";
  ctx.fillText(
    "Dr. Mohamed Gresha  •  Faculty of Computer and Information Systems  •  Egyptian Chinese University",
    800, 897
  );

  return canvas;
}

function drawCardField(ctx, label, value, x, y, maxWidth) {
  ctx.fillStyle = "#667085";
  ctx.textAlign = "left";
  ctx.font = "600 20px Arial, sans-serif";
  ctx.fillText(label, x, y);

  ctx.fillStyle = "#172033";
  ctx.font = "700 31px Arial, sans-serif";
  const safeValue = String(value || "");
  const fitted = fitText(ctx, safeValue, maxWidth);
  ctx.fillText(fitted, x, y + 48);
}

function fitText(ctx, text, maxWidth) {
  if (ctx.measureText(text).width <= maxWidth) return text;
  let result = text;
  while (result.length > 1 && ctx.measureText(result + "…").width > maxWidth) {
    result = result.slice(0, -1);
  }
  return result + "…";
}

function roundedRectPath(ctx, x, y, width, height, radius) {
  const r = Math.min(radius, width / 2, height / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + width, y, x + width, y + height, r);
  ctx.arcTo(x + width, y + height, x, y + height, r);
  ctx.arcTo(x, y + height, x, y, r);
  ctx.arcTo(x, y, x + width, y, r);
  ctx.closePath();
}

function drawContain(ctx, img, x, y, width, height) {
  const scale = Math.min(width / img.width, height / img.height);
  const w = img.width * scale;
  const h = img.height * scale;
  ctx.drawImage(img, x + (width - w) / 2, y + (height - h) / 2, w, h);
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error("Unable to load image: " + src));
    img.src = src;
  });
}

async function downloadPdf() {
  if (!generatedData?.qrDataUrl) {
    showToast("QR image is not ready.");
    return;
  }
  try {
    await downloadStudentPdf(generatedData);
  } catch (error) {
    console.error(error);
    showToast(error.message);
  }
}

function showToast(message) {
  const toast = document.getElementById("toast");
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(window.toastTimer);
  window.toastTimer = setTimeout(() => toast.classList.remove("show"), 2500);
}
